def parse_duration(text: str) -> int:
    import re

    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    parts = text.split()
    if not parts or not all(re.fullmatch(r"(\d+[dhms])+", part) for part in parts):
        raise ValueError(f"invalid duration: {text!r}")
    total = 0
    seen = set()
    for number, unit in re.findall(r"(\d+)([dhms])", text):
        if unit in seen:
            raise ValueError(f"unit {unit!r} repeated in {text!r}")
        seen.add(unit)
        total += int(number) * units[unit]
    return total

def next_business_day(date: str, holidays: list[str]) -> str:
    from datetime import date as Date, timedelta

    closed = set(holidays)
    day = Date.fromisoformat(date)
    while True:
        day += timedelta(days=1)
        if day.weekday() < 5 and day.isoformat() not in closed:
            return day.isoformat()

def wrap_text(text: str, width: int) -> list[str]:
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
